<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../services/userService.php';require_once __DIR__.'/../includes/auth.php';$pdo=openDatabase();$admin=requireLogin($pdo);requireRole($admin,['Administrator']);$id=filter_input(INPUT_GET,'user_id',FILTER_VALIDATE_INT);if(!$id||$id<1){http_response_code(400);exit('Invalid user ID');}$error='';$success='';$target=findUserById($pdo,$id);if(!$target){http_response_code(404);exit('User not found');}if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken($_POST);try{$action=(string)($_POST['action']??'');if($action==='role')adminChangeRole($pdo,$id,(string)($_POST['role']??''));elseif($action==='status')adminChangeStatus($pdo,$id,(string)($_POST['status']??''));elseif($action==='delete')adminDeleteUser($pdo,$id);else throw new InvalidArgumentException('Invalid action.');$success='Account updated.';$target=findUserById($pdo,$id);}catch(DomainException|InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->getMessage());$error='Unable to update account.';}}
require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?>
<main class="container py-4"><h1>Manage account #<?=$id?></h1><p><?=htmlspecialchars($target['full_name'],ENT_QUOTES,'UTF-8')?> (<?=htmlspecialchars($target['email'],ENT_QUOTES,'UTF-8')?>)</p><p>Current role: <?=htmlspecialchars($target['role'])?> | Status: <?=htmlspecialchars($target['status'])?></p><?php if($error):?><div class="alert alert-warning"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=$success?></div><?php endif;?><h2>Change role</h2><form method="post"><?=csrfField()?><input type="hidden" name="action" value="role"><select class="form-select" name="role"><?php foreach(['Student','Tutor','Administrator'] as $r):?><option value="<?=$r?>" <?=$r===$target['role']?'selected':''?>><?=$r?></option><?php endforeach;?></select><button class="btn btn-primary mt-2">Save role</button></form><hr><h2>Account status</h2><form method="post" onsubmit="return confirm('Confirm account status change?')"><?=csrfField()?><input type="hidden" name="action" value="status"><select class="form-select" name="status"><option value="Active">Active</option><option value="Inactive" <?=$target['status']==='Inactive'?'selected':''?>>Inactive</option></select><button class="btn btn-warning mt-2">Confirm status</button></form><hr><h2>Delete account (UM-08)</h2><p>Permanent deletion is blocked until a retention policy for related tutoring requests is approved.</p><form method="post" onsubmit="return confirm('Attempt to delete account? Related tutoring records will be checked. Deletion is currently blocked by policy.')"><?=csrfField()?><input type="hidden" name="action" value="delete"><button class="btn btn-outline-danger">Request deletion</button></form><p><a href="manage-users.php">Back to users</a></p></main><?php require __DIR__.'/../includes/footer.php';?>
